    const economics={attributed_sales:aggregate(src,'attributed_sales',src.start,src.end),gross_profit:aggregate(src,'gross_profit',src.start,src.end),ad_spend:aggregate(src,'ad_spend',src.start,src.end),promo_cost:aggregate(src,'promo_cost',src.start,src.end)};const costs=(economics.ad_spend||0)+(economics.promo_cost||0);economics.roi=economics.gross_profit!=null&&costs>0?(economics.gross_profit-costs)/costs:null;
