  function sourceSnapshot(d){const s=d.source;return{period:{start:s.start,end:s.end,prev_start:s.prevStart,prev_end:s.prevEnd},metrics:s.metrics.map(x=>({id:x.id,metric_key:x.metric_key,metric_value:x.metric_value,metric_unit:x.metric_unit,source:x.source,data_quality:x.data_quality,period_start:x.period_start,period_end:x.period_end,last_synced_at:x.last_synced_at,location_id:x.location_id,collection_frequency:x.collection_frequency,channel:x.channel})),tasks:s.tasks.map(x=>({id:x.id,title:x.title,status:x.status,priority:x.priority,completed_at:x.completed_at})),campaigns:s.campaigns.map(x=>({id:x.id,name:x.name,status:x.status,start_date:x.start_date,end_date:x.end_date})),production:s.production.map(x=>({id:x.id,production_goal:x.production_goal,status:x.status,scheduled_date:x.scheduled_date,actual_date:x.actual_date})),content:s.content.map(x=>({id:x.id,title:x.title,content_type:x.content_type,status:x.status})),systems:s.systems.map(x=>({id:x.id,system_name:x.system_name,connection_status:x.connection_status,data_export_available:x.data_export_available}))};}
